"""Configurations métier des contraintes de compte appliquées au backtesting.""" from __future__ import annotations
from dataclasses import dataclass from typing import Literal
LegacySmallAccountMode = Literal["standard", "pdt", "swing", "cash"] AccountType = Literal["margin", "cash"] PDTRule = Literal["auto", "off"]
@dataclass(frozen=True, slots=True) class TradingConstraintConfig: """Contraintes de compte applicables pendant un backtest.
Axes supportés -------------- - ``account_type`` : ``margin`` ou ``cash`` - ``pdt_rule`` : ``auto`` ou ``off`` - ``swing_only`` : interdit les sorties le jour même quand activé
Compatibilité legacy -------------------- Un pont `from_legacy_mode()` est conservé pour migrer l'ancien mode exclusif ``standard|pdt|swing|cash`` vers cette API plus expressive. """
account_type: AccountType = "margin" pdt_rule: PDTRule = "auto" swing_only: bool = False pdt_equity_threshold: float = 25_000.0 max_day_trades: int = 3 rolling_window_days: int = 5 cash_settlement_days: int = 1
@property def restrict_same_day_exit(self) -> bool: return self.swing_only
@property def use_settled_cash_only(self) -> bool: return self.account_type == "cash"
@property def effective_pdt_rule(self) -> PDTRule: if self.account_type == "cash": return "off" return self.pdt_rule
def applies_pdt_limit(self, equity: float) -> bool: return self.effective_pdt_rule == "auto" and equity < self.pdt_equity_threshold
def requires_stateful_simulation(self, equity: float) -> bool: return self.restrict_same_day_exit or self.use_settled_cash_only or self.applies_pdt_limit(equity)
@classmethod def from_legacy_mode(cls, mode: LegacySmallAccountMode) -> TradingConstraintConfig: mapping: dict[LegacySmallAccountMode, TradingConstraintConfig] = { "standard": cls(account_type="margin", pdt_rule="off", swing_only=False), "pdt": cls(account_type="margin", pdt_rule="auto", swing_only=False), "swing": cls(account_type="margin", pdt_rule="off", swing_only=True), "cash": cls(account_type="cash", pdt_rule="off", swing_only=False), } return mapping[mode]
def to_dict(self) -> dict[str, int | float | str | bool]: return { "account_type": self.account_type, "pdt_rule": self.pdt_rule, "effective_pdt_rule": self.effective_pdt_rule, "swing_only": self.swing_only, "pdt_equity_threshold": float(self.pdt_equity_threshold), "max_day_trades": int(self.max_day_trades), "rolling_window_days": int(self.rolling_window_days), "cash_settlement_days": int(self.cash_settlement_days), "restrict_same_day_exit": self.restrict_same_day_exit, "use_settled_cash_only": self.use_settled_cash_only, }

"""Configurations métier des contraintes de compte appliquées au backtesting."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

AccountType = Literal["margin", "cash"]
PDTRule = Literal["auto", "off"]


@dataclass(frozen=True, slots=True)
class TradingConstraintConfig:
    """Contraintes de compte applicables pendant un backtest.

    Axes supportés
    --------------
    - ``account_type`` : ``margin`` ou ``cash``
    - ``pdt_rule`` : ``auto`` ou ``off``
    - ``swing_only`` : interdit les sorties le jour même quand activé

    """

    account_type: AccountType = "margin"
    pdt_rule: PDTRule = "auto"
    swing_only: bool = False
    pdt_equity_threshold: float = 25_000.0
    max_day_trades: int = 3
    rolling_window_days: int = 5
    cash_settlement_days: int = 1

    @property
    def restrict_same_day_exit(self) -> bool:
        return self.swing_only

    @property
    def use_settled_cash_only(self) -> bool:
        return self.account_type == "cash"

    @property
    def effective_pdt_rule(self) -> PDTRule:
        if self.account_type == "cash":
            return "off"
        return self.pdt_rule

    def applies_pdt_limit(self, equity: float) -> bool:
        return self.effective_pdt_rule == "auto" and equity < self.pdt_equity_threshold

    def requires_stateful_simulation(self, equity: float) -> bool:
        return self.restrict_same_day_exit or self.use_settled_cash_only or self.applies_pdt_limit(equity)

    def to_dict(self) -> dict[str, int | float | str | bool]:
        return {
            "account_type": self.account_type,
            "pdt_rule": self.pdt_rule,
            "effective_pdt_rule": self.effective_pdt_rule,
            "swing_only": self.swing_only,
            "pdt_equity_threshold": float(self.pdt_equity_threshold),
            "max_day_trades": int(self.max_day_trades),
            "rolling_window_days": int(self.rolling_window_days),
            "cash_settlement_days": int(self.cash_settlement_days),
            "restrict_same_day_exit": self.restrict_same_day_exit,
            "use_settled_cash_only": self.use_settled_cash_only,
        }

""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

"""Couche d'isolation broker — seul ce fichier change si on change de broker."""
from __future__ import annotations

import logging
from datetime import datetime, timezone
from typing import Any

from execution_engine.config import ExecutionConfig
from execution_engine.models import BrokerOrder, OrderIntent, OrderStatus
from execution_engine.order_intents import intent_to_alpaca_payload
from execution_engine.state_machine import map_alpaca_status
from service.alpaca.trading_client import AlpacaTradingClient

LOGGER = logging.getLogger(__name__)


class BrokerAdapter:
    """Adapte AlpacaTradingClient vers les types internes execution_engine."""

    def __init__(self, client: AlpacaTradingClient, config: ExecutionConfig) -> None:
        self._client = client
        self._config = config

    def submit_intent(self, intent: OrderIntent) -> BrokerOrder:
        payload = intent_to_alpaca_payload(intent)
        resp = self._client.submit_order(payload)
        return self._resp_to_broker_order(resp, intent.intent_id)

    def poll_order_status(self, broker_order_id: str, intent_id: str = "") -> BrokerOrder:
        resp = self._client.get_order(broker_order_id)
        return self._resp_to_broker_order(resp, intent_id)

    def cancel_broker_order(self, broker_order_id: str) -> bool:
        return self._client.cancel_order(broker_order_id)

    def get_all_positions(self) -> list[dict[str, Any]]:
        return self._client.get_positions()  # type: ignore[return-value]

    def is_market_open(self) -> bool:
        return self._client.is_market_open()

    def get_account_equity(self) -> float:
        acc = self._client.get_account()
        return float(acc.get("equity", 0))

    @staticmethod
    def _resp_to_broker_order(resp: dict[str, Any], intent_id: str) -> BrokerOrder:
        def _ts(val: Any) -> datetime | None:
            if val is None:
                return None
            try:
                return datetime.fromisoformat(str(val).replace("Z", "+00:00"))
            except (ValueError, TypeError):
                return None

        return BrokerOrder(
            broker_order_id=str(resp.get("id", "")),
            client_order_id=str(resp.get("client_order_id", "")),
            intent_id=intent_id,
            symbol=str(resp.get("symbol", "")),
            side=str(resp.get("side", "")),
            qty=float(resp.get("qty", 0)),
            filled_qty=float(resp.get("filled_qty", 0)),
            avg_fill_price=float(resp["filled_avg_price"]) if resp.get("filled_avg_price") else None,
            status=map_alpaca_status(str(resp.get("status", "failed"))),
            order_type=str(resp.get("type", "")),
            limit_price=float(resp["limit_price"]) if resp.get("limit_price") else None,
            stop_price=float(resp["stop_price"]) if resp.get("stop_price") else None,
            trail_percent=float(resp["trail_percent"]) if resp.get("trail_percent") else None,
            created_at=_ts(resp.get("created_at")),
            updated_at=_ts(resp.get("updated_at")),
        )

