        args = parser.parse_args(["run", "--start", "2020-01-01", "--end", "2025-12-31", "--equity", "50000"])
        assert args.command == "run"
        assert args.start == "2020-01-01"
        assert args.end == "2025-12-31"
        assert args.equity == 50000

