class TestBacktestingRegistry:
    def test_start_backtesting_run_rejects_duplicate_active_kind(self, monkeypatch):
        from ihm.services import backtesting_registry
        from ihm.services.backtesting_runner import BacktestRunOptions

        monkeypatch.setattr(
            backtesting_registry,
            "list_active_backtesting_runs_by_kind",
            lambda run_kind: [{"run_id": "run-active-123", "run_kind": run_kind, "status": "running"}],
        )

        try:
            backtesting_registry.start_backtesting_run(
                "run",
                "Backtest complet",
                BacktestRunOptions(start="2025-04-21", end="2025-04-14"),
            )
        except RuntimeError as exc:
            assert "déjà en cours" in str(exc)
            assert "run-active-123" in str(exc)
        else:
            raise AssertionError("Le registre aurait dû bloquer un second run du même type.")

import pytest
from execution_engine.config import ExecutionConfig
@pytest.mark.parametrize( ("kwargs", "message"), [ ({"broker_mode": "sandbox"}, "broker_mode"), ({"entry_order_type": "stop"}, "entry_order_type"), ({"profit_taker_pct": 0}, "profit_taker_pct"), ({"trailing_stop_pct": 1}, "trailing_stop_pct"), ({"max_slippage_bps": 600}, "max_slippage_bps"), ({"max_order_retries": -1}, "max_order_retries"), ({"retry_base_delay_seconds": 0}, "retry_base_delay_seconds"), ({"inter_order_delay_ms": -1}, "inter_order_delay_ms"), ({"poll_interval_seconds": 0}, "poll_interval_seconds"), ({"fill_timeout_seconds": 0}, "fill_timeout_seconds"), ({"cancel_timeout_seconds": 0}, "cancel_timeout_seconds"), ({"execution_batch_size": 0}, "execution_batch_size"), ({"max_consecutive_failures": 0}, "max_consecutive_failures"), ], ) def test_execution_config_validates_invalid_values(kwargs, message): with pytest.raises(ValueError, match=message): ExecutionConfig(**kwargs)
def test_execution_config_is_paper_by_default() -> None: cfg = ExecutionConfig()
assert cfg.is_paper() is True assert cfg.is_live() is False
def test_execution_config_is_live_when_requested() -> None: cfg = ExecutionConfig(broker_mode="live")
assert cfg.is_live() is True assert cfg.is_paper() is False

import pytest
from execution_engine.config import ExecutionConfig
@pytest.mark.parametrize( ("kwargs", "message"), [ ({"broker_mode": "sandbox"}, "broker_mode"), ({"account_type": "leveraged"}, "account_type"), ({"pdt_rule": "strict"}, "pdt_rule"), ({"entry_order_type": "stop"}, "entry_order_type"), ({"profit_taker_pct": 0}, "profit_taker_pct"), ({"trailing_stop_pct": 1}, "trailing_stop_pct"), ({"max_slippage_bps": 600}, "max_slippage_bps"), ({"max_order_retries": -1}, "max_order_retries"), ({"retry_base_delay_seconds": 0}, "retry_base_delay_seconds"), ({"inter_order_delay_ms": -1}, "inter_order_delay_ms"), ({"poll_interval_seconds": 0}, "poll_interval_seconds"), ({"fill_timeout_seconds": 0}, "fill_timeout_seconds"), ({"cancel_timeout_seconds": 0}, "cancel_timeout_seconds"), ({"execution_batch_size": 0}, "execution_batch_size"), ({"max_consecutive_failures": 0}, "max_consecutive_failures"), ({"pdt_equity_threshold": 0}, "pdt_equity_threshold"), ({"max_day_trades": 0}, "max_day_trades"), ({"cash_settlement_days": 0}, "cash_settlement_days"), ({"simulated_account_equity": 0}, "simulated_account_equity"), ({"simulated_margin_buying_power_multiplier": 0.5}, "simulated_margin_buying_power_multiplier"), ], ) def test_execution_config_validates_invalid_values(kwargs, message): with pytest.raises(ValueError, match=message): ExecutionConfig(**kwargs)
def test_execution_config_is_paper_by_default() -> None: cfg = ExecutionConfig()
assert cfg.is_paper() is True assert cfg.is_live() is False
def test_execution_config_is_live_when_requested() -> None: cfg = ExecutionConfig(broker_mode="live")
assert cfg.is_live() is True assert cfg.is_paper() is False
def test_execution_config_disables_effective_pdt_for_cash_account() -> None: cfg = ExecutionConfig(account_type="cash", pdt_rule="auto")
assert cfg.effective_pdt_rule == "off" assert cfg.applies_pdt_limit(2_000.0) is False
